import sys
import heapq

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        V = int(next(iterator))
        E = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(V)]

    for _ in range(E):
        u = int(next(iterator))
        v = int(next(iterator))
        w = int(next(iterator))
        adj[u].append((v, w))

    s = int(next(iterator))
    t = int(next(iterator))

    dist = [float('inf')] * V
    count = [0] * V

    dist[s] = 0
    count[s] = 1

    pq = [(0, s)]

    while pq:
        d, u = heapq.heappop(pq)

        if d > dist[u]:
            continue

        for v, w in adj[u]:
            new_dist = d + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                count[v] = count[u]
                heapq.heappush(pq, (new_dist, v))
            elif new_dist == dist[v]:
                count[v] += count[u]

    if dist[t] == float('inf'):
        print(0)
    else:
        print(count[t])

if __name__ == "__main__":
    main()
